cssCode:
.cube-scene {
  width: 120px; height: 120px;
  perspective: 800px;
}
.cube {
  width: 100%; height: 100%; position: relative;
  transform-style: preserve-3d;
  animation: spinCube 6s infinite linear;
}
.cube-face {
  position: absolute; width: 120px; height: 120px;
  background: rgba(0, 255, 204, 0.1);
  border: 2px solid #00ffcc;
  box-shadow: 0 0 20px rgba(0, 255, 204, 0.5), inset 0 0 20px rgba(0, 255, 204, 0.5);
  display: flex; align-items: center; justify-content: center;
  font-family: monospace; font-size: 20px; color: #fff; font-weight: bold;
}
.front  { transform: rotateY(0deg) translateZ(60px); }
.right  { transform: rotateY(90deg) translateZ(60px); }
.back   { transform: rotateY(180deg) translateZ(60px); }
.left   { transform: rotateY(-90deg) translateZ(60px); }
.top    { transform: rotateX(90deg) translateZ(60px); }
.bottom { transform: rotateX(-90deg) translateZ(60px); }

@keyframes spinCube {
  0% { transform: rotateX(0deg) rotateY(0deg); }
  100% { transform: rotateX(360deg) rotateY(360deg); }
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const scene = document.createElement('div');
scene.className = 'cube-scene';
const cube = document.createElement('div');
cube.className = 'cube';

const faces = ['front', 'right', 'back', 'left', 'top', 'bottom'];
faces.forEach(face => {
  const div = document.createElement('div');
  div.className = `cube-face ${face}`;
  div.innerText = 'PRO';
  cube.appendChild(div);
});

scene.appendChild(cube);
c.appendChild(scene);
